package dev.veltraph.client.inventory.bottle;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.inventory.bottle.BottleFillReceipts.*;
class BottleMatchedReceiptTest {
    final BottleFillReceipts journal=new BottleFillReceipts();
    final Scope scope=new Scope(new Object(),new Object(),new Object(),new Object(),new Object(),4);
    final Cell glass=new Cell(new BottleFillWorkflow.Stack(BottleFillWorkflowTest.GLASS,63,false),"full-glass"),water=new Cell(new BottleFillWorkflow.Stack(BottleFillWorkflowTest.WATER,1,false),"full-water"),empty=new Cell(BottleFillWorkflow.Stack.EMPTY,"full-empty");
    @Test void exactMatchedReceiptKeepsOriginalKindRevisionSequenceAndScope(){journal.applied(scope,Kind.CONTAINER_CONTENT,12,Map.of(6,water),Map.of());journal.applied(scope,Kind.CONTAINER_SLOT,13,Map.of(8,glass),Map.of());var match=journal.containerWitness(scope,0,Map.of(6,water),Map.of(),10).orElseThrow();assertEquals(1,match.receipts().size());var receipt=match.receipts().getFirst();assertEquals(1,receipt.sequence(),"Unrelated later packet is not matched evidence");assertEquals(12,receipt.revision());assertEquals(Kind.CONTAINER_CONTENT,receipt.kind());assertSame(scope,receipt.scope());}
    @Test void nativePlayerSlotMinusOneNeverBecomesContainerRevision(){journal.applied(scope,Kind.PLAYER_SLOT,-1,Map.of(6,water),Map.of());var receipt=journal.matched(scope,0,Map.of(6,water),Map.of(),0).orElseThrow().receipts().getFirst();assertEquals(-1,receipt.revision());assertEquals(Kind.PLAYER_SLOT,receipt.kind());assertTrue(journal.confirms(scope,0,Map.of(6,water),Map.of(),0));assertTrue(journal.containerWitness(scope,0,Map.of(6,water),Map.of(),0).isEmpty());}
    @Test void latestPlayerPacketCannotBorrowAnOlderContainerRevision(){journal.applied(scope,Kind.CONTAINER_CONTENT,7,Map.of(6,water),Map.of());journal.applied(scope,Kind.PLAYER_SLOT,-1,Map.of(6,water),Map.of());assertEquals(2,journal.matched(scope,0,Map.of(6,water),Map.of(),0).orElseThrow().receipts().getFirst().sequence());assertTrue(journal.containerWitness(scope,0,Map.of(6,water),Map.of(),0).isEmpty());}
    @Test void distinctPacketsMustCoverEveryExactIssuedCell(){journal.applied(scope,Kind.CONTAINER_SLOT,5,Map.of(0,glass),Map.of());assertTrue(journal.matched(scope,0,Map.of(0,glass,6,water),Map.of(),0).isEmpty());journal.applied(scope,Kind.CONTAINER_SLOT,6,Map.of(6,water),Map.of());var match=journal.containerWitness(scope,0,Map.of(0,glass,6,water),Map.of(),5).orElseThrow();assertEquals(List.of(1L,2L),match.receipts().stream().map(Receipt::sequence).toList());}
    @Test void samePacketCoveringMultipleCellsIsReturnedOnceAndImmutable(){journal.applied(scope,Kind.CONTAINER_CONTENT,5,Map.of(0,glass,6,water),Map.of(2,empty));var match=journal.containerWitness(scope,0,Map.of(0,glass,6,water),Map.of(2,empty),5).orElseThrow();assertEquals(1,match.receipts().size());assertThrows(UnsupportedOperationException.class,()->match.receipts().clear());assertThrows(UnsupportedOperationException.class,()->match.receipts().getFirst().player().clear());}
    @Test void staleScopeSequenceLowRevisionAndCanonicalMismatchReject(){journal.applied(scope,Kind.CONTAINER_CONTENT,5,Map.of(6,water),Map.of());assertTrue(journal.containerWitness(scope,1,Map.of(6,water),Map.of(),0).isEmpty());assertTrue(journal.containerWitness(scope,0,Map.of(6,water),Map.of(),6).isEmpty());assertTrue(journal.containerWitness(new Scope(scope.player(),scope.world(),scope.connection(),new Object(),scope.screen(),4),0,Map.of(6,water),Map.of(),0).isEmpty());assertTrue(journal.containerWitness(scope,0,Map.of(6,new Cell(water.stack(),"different-full-components")),Map.of(),0).isEmpty());}
    @Test void newerContradictionRevokesOldReceiptRatherThanSkippingIt(){journal.applied(scope,Kind.CONTAINER_CONTENT,5,Map.of(6,water),Map.of());journal.applied(scope,Kind.CONTAINER_SLOT,6,Map.of(6,empty),Map.of());assertTrue(journal.matched(scope,0,Map.of(6,water),Map.of(),0).isEmpty());assertFalse(journal.confirms(scope,0,Map.of(6,water),Map.of(),0));}
    @Test void mixedStoreRetainsLegacyConfirmationButCannotSupplyFinancialContainerProof(){journal.applied(scope,Kind.PLAYER_SLOT,-1,Map.of(6,empty),Map.of());journal.applied(scope,Kind.CONTAINER_SLOT,9,Map.of(),Map.of(0,water));assertTrue(journal.confirms(scope,0,Map.of(6,empty),Map.of(0,water),9));assertEquals(2,journal.matched(scope,0,Map.of(6,empty),Map.of(0,water),9).orElseThrow().receipts().size());assertTrue(journal.containerWitness(scope,0,Map.of(6,empty),Map.of(0,water),9).isEmpty());}
    @Test void changedNativeScopeClearsEvidenceAndEmptyRequestsHaveNoReceipt(){journal.applied(scope,Kind.CONTAINER_CONTENT,5,Map.of(6,water),Map.of());var foreign=new Scope(scope.player(),scope.world(),new Object(),scope.menu(),scope.screen(),4);journal.applied(foreign,Kind.CONTAINER_CONTENT,6,Map.of(6,water),Map.of());assertTrue(journal.matched(scope,0,Map.of(6,water),Map.of(),0).isEmpty());assertTrue(journal.matched(foreign,0,Map.of(),Map.of(),0).isEmpty());}
}
